{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "jobs" });

  const qualifying = issues.filter(i => i.status === "unresolved" && i.count >= 80);

  // Dedupe culprits, keeping the Sentry issues that led to each one.
  const byCulprit = new Map<string, { shortId: string; count: number }[]>();
  for (const i of qualifying) {
    const list = byCulprit.get(i.culprit) ?? [];
    list.push({ shortId: i.shortId, count: i.count });
    byCulprit.set(i.culprit, list);
  }

  const plan: any[] = [];
  for (const [culprit, sentryIssues] of byCulprit) {
    // Search broadly, then confirm the culprit text actually appears in a hit.
    const queries = [culprit, culprit.split(" in ")[1] ?? culprit, culprit.split(" in ")[0]];
    const seen = new Set<string>();
    const matches: any[] = [];
    for (const q of queries) {
      const { issues: hits } = await sdk.linear.searchIssues({ query: q });
      for (const h of hits) {
        if (seen.has(h.identifier)) continue;
        seen.add(h.identifier);
        if ((h.title ?? "").includes(culprit) || (h.description ?? "").includes(culprit)) {
          matches.push({ identifier: h.identifier, title: h.title, state: h.state });
        }
      }
    }

    if (matches.length > 0) {
      plan.push({ culprit, sentryIssues, action: "skip: already in Linear", existing: matches });
      continue;
    }

    const created = await sdk.linear.createIssue({
      title: `[Sentry] ${culprit}`,
      description: culprit,
    });
    plan.push({ culprit, sentryIssues, action: "create", title: `[Sentry] ${culprit}`, created });
  }

  return { qualifyingSentryIssues: qualifying.length, distinctCulprits: byCulprit.size, plan };
}", "input": {}}

